// Joins all migrations into one file, supabase/setup.sql, so the whole
// database can be created by pasting a single file into the Supabase
// SQL Editor. Run with: npm run db:bundle
import fs from "node:fs";
import path from "node:path";

const dir = "supabase/migrations";
const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const header = `-- Borrow Buddy · complete database setup
-- GENERATED by "npm run db:bundle" from supabase/migrations. Don't edit by hand.
-- Paste this whole file into Supabase → SQL Editor → New query, then click Run.
-- Run it once, on a new, empty project.

`;
const body = files
  .map((f) => `-- >>> ${f}\n${fs.readFileSync(path.join(dir, f), "utf8").trim()}\n`)
  .join("\n");
fs.writeFileSync("supabase/setup.sql", header + body);
console.log(`Wrote supabase/setup.sql from ${files.length} migrations.`);
